export function findingExportAvailability(scan, findingCount) {
  if (!FINDING_EXPORT_STATUSES.includes(scan.status)) {
    return {
      ready: false,
      message: 'Findings can be exported after the scan completes, stops, or fails.',
    };
  }
  if (!findingCount) {
